  final PVNObjectBuilder? _PROVENANCE;
  final String? _CREATED_AT;
  final String? _UPDATED_AT;
  final List<int>? _SIGNATURE;

  THPObjectBuilder({
    String? THP_ID,
    String? thpId,
    String? NAME,
    String? DESCRIPTION,
    thpThreatCategory? CATEGORY,
    thpAccessTier? ACCESS_TIER,
    thpAccessTier? accessTier,
    bool? ACTIVE,
    String? LINKED_SCHEMA,
    String? linkedSchema,
    String? LINKED_RECORD_ID,
    String? linkedRecordId,
    int? LINKED_NORAD_CAT_ID,
    int? linkedNoradCatId,
    List<THPReferenceObjectBuilder>? ADDITIONAL_REFS,
    List<THPReferenceObjectBuilder>? additionalRefs,
    List<THPParameterObjectBuilder>? PARAMETERS,
    PVNObjectBuilder? PROVENANCE,
    String? CREATED_AT,
    String? createdAt,
    String? UPDATED_AT,
    String? updatedAt,
    List<int>? SIGNATURE,
  })
      : _THP_ID = thpId ?? THP_ID,
        _NAME = NAME,
        _DESCRIPTION = DESCRIPTION,
        _CATEGORY = CATEGORY,
        _ACCESS_TIER = accessTier ?? ACCESS_TIER,
        _ACTIVE = ACTIVE,
        _LINKED_SCHEMA = linkedSchema ?? LINKED_SCHEMA,
        _LINKED_RECORD_ID = linkedRecordId ?? LINKED_RECORD_ID,
        _LINKED_NORAD_CAT_ID = linkedNoradCatId ?? LINKED_NORAD_CAT_ID,
        _ADDITIONAL_REFS = additionalRefs ?? ADDITIONAL_REFS,
        _PARAMETERS = PARAMETERS,
        _PROVENANCE = PROVENANCE,
        _CREATED_AT = createdAt ?? CREATED_AT,
        _UPDATED_AT = updatedAt ?? UPDATED_AT,
        _SIGNATURE = SIGNATURE;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? THP_IDOffset = _THP_ID == null ? null
        : fbBuilder.writeString(_THP_ID!);
    final int? NAMEOffset = _NAME == null ? null
        : fbBuilder.writeString(_NAME!);
    final int? DESCRIPTIONOffset = _DESCRIPTION == null ? null
        : fbBuilder.writeString(_DESCRIPTION!);
    final int? LINKED_SCHEMAOffset = _LINKED_SCHEMA == null ? null
        : fbBuilder.writeString(_LINKED_SCHEMA!);
    final int? LINKED_RECORD_IDOffset = _LINKED_RECORD_ID == null ? null
        : fbBuilder.writeString(_LINKED_RECORD_ID!);
    final int? ADDITIONAL_REFSOffset = _ADDITIONAL_REFS == null ? null
        : fbBuilder.writeList(_ADDITIONAL_REFS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? PARAMETERSOffset = _PARAMETERS == null ? null
        : fbBuilder.writeList(_PARAMETERS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? PROVENANCEOffset = _PROVENANCE?.getOrCreateOffset(fbBuilder);
    final int? CREATED_ATOffset = _CREATED_AT == null ? null
        : fbBuilder.writeString(_CREATED_AT!);
    final int? UPDATED_ATOffset = _UPDATED_AT == null ? null
        : fbBuilder.writeString(_UPDATED_AT!);
    final int? SIGNATUREOffset = _SIGNATURE == null ? null
        : fbBuilder.writeListUint8(_SIGNATURE!);
    fbBuilder.startTable(15);
    fbBuilder.addOffset(0, THP_IDOffset);
    fbBuilder.addOffset(1, NAMEOffset);
    fbBuilder.addOffset(2, DESCRIPTIONOffset);
    fbBuilder.addInt8(3, _CATEGORY?.value);
    fbBuilder.addInt8(4, _ACCESS_TIER?.value);
    fbBuilder.addBool(5, _ACTIVE);
    fbBuilder.addOffset(6, LINKED_SCHEMAOffset);
    fbBuilder.addOffset(7, LINKED_RECORD_IDOffset);
    fbBuilder.addUint32(8, _LINKED_NORAD_CAT_ID);
    fbBuilder.addOffset(9, ADDITIONAL_REFSOffset);
    fbBuilder.addOffset(10, PARAMETERSOffset);
    fbBuilder.addOffset(11, PROVENANCEOffset);
    fbBuilder.addOffset(12, CREATED_ATOffset);
    fbBuilder.addOffset(13, UPDATED_ATOffset);
    fbBuilder.addOffset(14, SIGNATUREOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
